import React from 'react';
import {
	FormControl,
	FormLabel,
	Heading,
	Input,
	Link,
	Radio,
	RadioGroup,
	useDisclosure,
	VStack,
	Text,
} from '@chakra-ui/react';
import { format } from 'date-fns';
import { DateFormatInstructions } from './instructions';
import type { ICalendarPlusSettings } from '../../lib';

interface IDateSettingsProps {
	settings: ICalendarPlusSettings;
	formatErrors: { date?: string; month?: string; time?: string };
	handleDateFormatChange: (value: string) => void;
	handleMonthFormatChange: (value: string) => void;
	handleTimeFormatChange: (value: string) => void;
	handleCustomFormatChange: (type: 'date' | 'month' | 'time') => (event: React.ChangeEvent<HTMLInputElement>) => void;
}

const currentDateTime = new Date();

export const DateSettings: React.FunctionComponent<IDateSettingsProps> = ({
	settings,
	formatErrors,
	handleDateFormatChange,
	handleMonthFormatChange,
	handleTimeFormatChange,
	handleCustomFormatChange,
}) => {
	const { isOpen, onOpen, onClose } = useDisclosure();

	return (
		<>
			<Heading mb={4}>Date Formats</Heading>
			<Text fontSize='16px'>
				For creating custom formats check the following:&nbsp;
				<Link mt={4} color='blue.500' onClick={onOpen} cursor='pointer'>
					Format Instructions
				</Link>
			</Text>
			<FormControl mt={8}>
				<FormLabel>Date Format</FormLabel>
				<RadioGroup value={settings.dateFormat} onChange={handleDateFormatChange} pl='150px'>
					<VStack alignItems='flex-start' spacing={2}>
						<Radio value='yyyy-MM-dd'> {format(currentDateTime, 'yyyy-MM-dd')} ( yyyy-MM-dd )</Radio>
						<Radio value='MM/dd/yyyy'> {format(currentDateTime, 'MM/dd/yyyy')} ( MM/dd/yyyy) </Radio>
						<Radio value='dd-MM-yyyy'>{format(currentDateTime, 'dd-MM-yyyy')} ( dd-MM-yyyy )</Radio>
						<Radio value='dd/MM/yyyy'>{format(currentDateTime, 'dd/MM/yyyy')} ( dd/MM/yyyy )</Radio>
						<Radio value='dd.MM.yyyy'>{format(currentDateTime, 'dd.MM.yyyy')} ( dd.MM.yyyy )</Radio>
						<Radio value='custom'>Custom</Radio>
					</VStack>
				</RadioGroup>
				{settings.dateFormat === 'custom' && (
					<>
						<Input
							mt={2}
							id='customDateFormat'
							placeholder='Custom format (e.g., yyyy/MM/dd)'
							value={settings.customDateFormat}
							onChange={handleCustomFormatChange('date')}
						/>
						{formatErrors.date && <Text color='red.500'>{formatErrors.date}</Text>}
					</>
				)}
			</FormControl>

			<FormControl mt={8}>
				<FormLabel>Month Format</FormLabel>
				<RadioGroup value={settings.monthFormat} onChange={handleMonthFormatChange} pl='150px'>
					<VStack alignItems='flex-start' spacing={2}>
						<Radio value='MMMM dd'> {format(currentDateTime, 'MMMM dd')} ( MMMM dd )</Radio>
						<Radio value='dd MMMM'> {format(currentDateTime, 'dd MMMM')} ( dd MMMM )</Radio>
						<Radio value='MMM dd'> {format(currentDateTime, 'MMM dd')} ( MMM dd )</Radio>
						<Radio value='MM/dd'> {format(currentDateTime, 'MM/dd')} ( MM/dd )</Radio>
						<Radio value='custom'>Custom</Radio>
					</VStack>
				</RadioGroup>
				{settings.monthFormat === 'custom' && (
					<>
						<Input
							mt={2}
							id='customMonthFormat'
							placeholder='Custom format (e.g., dd MMMM)'
							value={settings.customMonthFormat}
							onChange={handleCustomFormatChange('month')}
						/>
						{formatErrors.month && <Text color='red.500'>{formatErrors.month}</Text>}
					</>
				)}
			</FormControl>

			<FormControl mt={8}>
				<FormLabel>Time Format</FormLabel>
				<RadioGroup value={settings.timeFormat} onChange={handleTimeFormatChange} pl='150px'>
					<VStack alignItems='flex-start' spacing={2}>
						<Radio value='HH:mm'>24-hour (HH:mm)</Radio>
						<Radio value='hh:mm a'>12-hour (hh:mm a)</Radio>
						<Radio value='custom'>Custom</Radio>
					</VStack>
				</RadioGroup>
				{settings.timeFormat === 'custom' && (
					<>
						<Input
							mt={2}
							id='customTimeFormat'
							placeholder='Custom format (e.g., hh:mm:ss)'
							value={settings.customTimeFormat}
							onChange={handleCustomFormatChange('time')}
						/>
						{formatErrors.time && <Text color='red.500'>{formatErrors.time}</Text>}
					</>
				)}
			</FormControl>

			<DateFormatInstructions isOpen={isOpen} onClose={onClose} />
		</>
	);
};
